import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8792/tests/alunix-r8/runs/V3d/index.html"

async def measure(pg, width):
    await pg.set_viewport_size({"width": width, "height": 900})
    await pg.wait_for_timeout(300)
    data = await pg.evaluate('''() => {
      const h = document.querySelector('.thesis-headline');
      const p = document.querySelector('.thesis-support');
      const fig = document.querySelector('.thesis-figure');
      const text = document.querySelector('.thesis-text');
      const hr = h.getBoundingClientRect();
      const pr = p.getBoundingClientRect();
      const fr = fig.getBoundingClientRect();
      const tr = text.getBoundingClientRect();
      // count rendered lines via getClientRects on a range covering the text node
      function lineCount(el){
        const range = document.createRange();
        range.selectNodeContents(el);
        const rects = range.getClientRects();
        return rects.length;
      }
      return {
        width: window.innerWidth,
        textColWidth: Math.round(tr.width),
        headlineWidth: Math.round(hr.width),
        headlineLines: lineCount(h),
        paraWidth: Math.round(pr.width),
        figRight: Math.round(fr.right), figWidth: Math.round(fr.width),
        figWidthPct: Math.round(1000*fr.width/window.innerWidth)/10,
      };
    }''')
    return data

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page()
        for attempt in range(5):
            try:
                await pg.goto(URL, wait_until="load", timeout=15000)
                break
            except Exception:
                if attempt == 4: raise
        for w in [768, 1024, 1280, 1440, 1920]:
            d = await measure(pg, w)
            print(d)
        await browser.close()

asyncio.run(main())

