URL = "http://127.0.0.1:8792/tests/alunix-r8/runs/V3d/index.html"

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page(viewport={"width":1440,"height":900})
        for attempt in range(5):
            try:
                await pg.goto(URL, wait_until="load", timeout=15000)
                break
            except Exception:
                if attempt==4: raise
        data = await pg.evaluate('''() => {
          const p = document.querySelector('.thesis-support');
          const cs = getComputedStyle(p);
          // measure "0" char width in this font/size to get 1ch
          const span = document.createElement('span');
          span.style.font = cs.font;
          span.style.position = 'absolute'; span.style.visibility='hidden';
          span.textContent = '0';
          document.body.appendChild(span);
          const chWidth = span.getBoundingClientRect().width;
          document.body.removeChild(span);
          const pr = p.getBoundingClientRect();
          return {fontSize: cs.fontSize, chWidth, paraWidthPx: pr.width, paraWidthCh: pr.width/chWidth};
        }''')
        print(data)
        await browser.close()

asyncio.run(main())

