import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8792/tests/alunix-r8/runs/V3d/index.html"

async def measure(pg, width):
    await pg.set_viewport_size({"width": width, "height": 900})
    await pg.wait_for_timeout(200)
    data = await pg.evaluate('''() => {
      // check every heading-like element on the page for split words
      const sels = ['h1','h2','h3','.thesis-headline','.hero-headline','.giant'];
      const results = [];
      document.querySelectorAll(sels.join(',')).forEach(el => {
        const text = el.textContent.trim();
        if (!text) return;
        const words = text.split(/\\s+/);
        const range = document.createRange();
        // get line rects
        range.selectNodeContents(el);
        const rects = [...range.getClientRects()];
        const lineCount = rects.length;
        // detect split word: walk each word, wrap in a temp marker via Range per-word bounding box,
        // check if a single word's glyphs span more than one line rect vertically
        let splitWord = null;
        const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
        let node;
        while (node = walker.nextNode()) {
          const t = node.textContent;
          let idx = 0;
          for (const w of t.split(/(\\s+)/)) {
            if (w.trim().length > 1 && !/\\s/.test(w)) {
              const r = document.createRange();
              r.setStart(node, idx);
              r.setEnd(node, idx + w.length);
              const wrects = r.getClientRects();
              if (wrects.length > 1) {
                // check horizontal overlap absence => genuinely wrapped mid-word (not just a ligature artifact)
                const tops = new Set([...wrects].map(x => Math.round(x.top)));
                if (tops.size > 1) { splitWord = w; }
              }
            }
            idx += w.length;
          }
        }
        results.push({tag: el.tagName, cls: el.className, text: text.slice(0,40), lineCount, splitWord});
      });
      return results;
    }''')
    return {"width": width, "results": data}

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page()
        for attempt in range(5):
            try:
                await pg.goto(URL, wait_until="load", timeout=15000)
                break
            except Exception:
                if attempt==4: raise
        for w in [768, 1024, 1280, 1440, 1920]:
            d = await measure(pg, w)
            print(d["width"])
            for r in d["results"]:
                flag = " <<< SPLIT" if r["splitWord"] else ""
                print("  ", r["cls"], r["lineCount"], "lines", flag, r["splitWord"] or "")
        await browser.close()

asyncio.run(main())

