import asyncio, time
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8792/tests/alunix-r8/runs/V3d/index.html"

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page(viewport={"width":1440,"height":900})
        for attempt in range(5):
            try:
                await pg.goto(URL, wait_until="load", timeout=15000)
                break
            except Exception:
                if attempt==4: raise
        await pg.wait_for_timeout(400)
        await pg.mouse.move(720, 450)
        t0 = time.time()
        step = 0
        while True:
            await pg.mouse.wheel(0, 800)
            await pg.wait_for_timeout(120)
            y = await pg.evaluate("window.scrollY")
            data = await pg.evaluate('''() => {
              const c = document.querySelector('.calyx-fig iframe');
              const h = document.querySelector('.horai-fig iframe');
              function info(f){
                if (!f) return null;
                return {hasSrc: !!f.getAttribute('src'), dataSrc: f.getAttribute('data-src'), complete: f.contentDocument ? f.contentDocument.readyState : 'n/a'};
              }
              return {calyx: info(c), horai: info(h)};
            }''')
            print(f"t={time.time()-t0:.2f}s step{step} y={y}", data)
            await pg.screenshot(path=rf"C:\Users\ANTONL~1\AppData\Local\Temp\claude\C--Users-Anton-L-anti-slop-design\7828381c-3671-4158-93de-9bec99c374f5\scratchpad\repro_{step:02d}_y{y}.png")
            step += 1
            if y > 6300 or step > 12:
                break
        await browser.close()

asyncio.run(main())

