import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8792/tests/alunix-r8/runs/V3d/index.html"

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page(viewport={"width":1440,"height":900})
        for attempt in range(5):
            try:
                await pg.goto(URL, wait_until="load", timeout=15000)
                break
            except Exception:
                if attempt==4: raise
        await pg.wait_for_timeout(500)
        await pg.evaluate("window.scrollTo(0,4000)")
        await pg.wait_for_timeout(600)
        data = await pg.evaluate('''() => {
          const els = document.elementsFromPoint(300, 250);
          return els.slice(0,8).map(e => ({tag: e.tagName, cls: (e.className||'').toString().slice(0,50), id: e.id}));
        }''')
        print("elementsFromPoint(300,250):", data)
        data2 = await pg.evaluate('''() => {
          function info(sel){
            const el = document.querySelector(sel);
            if (!el) return null;
            const r = el.getBoundingClientRect();
            const cs = getComputedStyle(el);
            return {sel, top: Math.round(r.top), bottom: Math.round(r.bottom), height: Math.round(r.height), position: cs.position};
          }
          return [
            info('#process'), info('.process-stick'), info('.process-steps'),
            info('#pris'), info('footer'), info('.panel-giant'), info('.stagger'),
          ];
        }''')
        for d in data2: print(d)
        await browser.close()

asyncio.run(main())

