import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8792/tests/alunix-r8/runs/V3d/index.html"

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page(viewport={"width":1440,"height":900})
        for attempt in range(5):
            try:
                await pg.goto(URL, wait_until="load", timeout=15000)
                break
            except Exception:
                if attempt==4: raise
        await pg.wait_for_timeout(700)
        data = await pg.evaluate('''() => {
          const bands = [...document.querySelectorAll('.step-band')];
          return bands.map((b, i) => {
            const li = b.closest('li');
            return {i, step: li ? li.getAttribute('data-step') : null, scrollHeight: b.scrollHeight, clientHeight: b.clientHeight};
          });
        }''')
        for d in data: print(d)
        await browser.close()

asyncio.run(main())

