import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8792/tests/alunix-r8/runs/V3d/index.html"

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        pg = await browser.new_page(viewport={"width":1440,"height":900})
        for attempt in range(5):
            try:
                await pg.goto(URL, wait_until="load", timeout=15000)
                break
            except Exception:
                if attempt==4: raise
        await pg.wait_for_timeout(500)
        data = await pg.evaluate('''() => {
          const band = document.querySelector('.step-band');
          function walk(el, depth){
            if (depth > 4) return [];
            const out = [];
            for (const child of el.children){
              const r = child.getBoundingClientRect();
              out.push({tag: child.tagName, cls: (child.className||'').toString().slice(0,40), h: Math.round(r.height), sh: child.scrollHeight});
              out.push(...walk(child, depth+1).map(x => ({...x, tag: '  '+x.tag})));
            }
            return out;
          }
          return walk(band, 0);
        }''')
        for d in data: print(d)
        await browser.close()

asyncio.run(main())

