import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8792/tests/alunix-r8/runs/V3d/index.html"
WIDTHS = [320, 375, 390, 768, 1024, 1280, 1440]

async def main():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        for w in WIDTHS:
            pg = await browser.new_page(viewport={"width": w, "height": 900})
            for attempt in range(8):
                try:
                    await pg.goto(URL, wait_until="load", timeout=15000)
                    break
                except Exception:
                    if attempt == 7: raise
            await pg.wait_for_timeout(600)
            data = await pg.evaluate('''() => {
              const docW = document.documentElement.scrollWidth;
              const vw = window.innerWidth;
              return {docScrollWidth: docW, viewportWidth: vw, overflow: docW > vw + 1};
            }''')
            print(w, data)
            await pg.close()
        await browser.close()

asyncio.run(main())

